using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

public class FishM1PatchAsset
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();

        UnityEngine.Object session = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Assets/Data/Config/FishingSession_Island1.asset");

        if (session == null)
        {
            Debug.LogError("[FishM1PatchAsset] 会话配置未找到");
            return;
        }

        SerializedObject serialized = new SerializedObject(session);

        if (!writeFloat(serialized, "BaseFishCountPerSlice", 3f, sb))
            return;

        writeFloat(serialized, "HazardSpawnChance", 0.15f, sb);
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorUtility.SetDirty(session);
        AssetDatabase.SaveAssets();
        sb.AppendLine("SAVED session asset");

        Scene scene = default;

        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            Scene candidate = SceneManager.GetSceneAt(i);

            if (candidate.name == "Fishing" && candidate.isLoaded)
                scene = candidate;
        }

        if (!scene.IsValid())
        {
            sb.AppendLine("SKIP  Fishing scene not open, line preview not patched");
            Debug.Log("[FishM1PatchAsset]\n" + sb);
            return;
        }

        GameObject hook = GameObject.Find("World/Hook");
        GameObject rodAnchor = GameObject.Find("World/Rod/LineAnchor");
        LineRenderer line = hook != null ? hook.GetComponent<LineRenderer>() : null;

        if (line == null || rodAnchor == null)
        {
            sb.AppendLine("SKIP  LineRenderer or LineAnchor missing");
            Debug.Log("[FishM1PatchAsset]\n" + sb);
            return;
        }

        line.SetPosition(0, rodAnchor.transform.position);
        line.SetPosition(1, hook.transform.position);
        EditorUtility.SetDirty(line);
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("SAVED scene, line endpoints previewed");

        Debug.Log("[FishM1PatchAsset]\n" + sb);
    }

    private static bool writeFloat(SerializedObject serialized, string property, float value, StringBuilder sb)
    {
        SerializedProperty found = serialized.FindProperty(property);

        if (found == null)
        {
            sb.AppendLine("NOPRP " + property);
            return false;
        }

        found.floatValue = value;
        sb.AppendLine("SET   " + property + " = " + value);
        return true;
    }
}
